while skill 'fishing' < 80
    if not findtype 3520 'lefthand'
        if findtype 3520 'backpack' as pole
            clearhands 'both'            
            lift pole 'backpack'
            drop 'self' lefthand
        else
            overhead "No more fishing poles."
            break
        endif
    endif
dclick lefthand
wait 8700
endwhile

// ============================================
// WIZARD'S HAT HEALING TRAINER
// ============================================
//
// SKILLS (English):
// - Healing: lets you use bandages to restore hit points on yourself or other targets.
// - This script trains Healing by equipping/unequipping Wizard's Hat and using Bandage Self.
// - Wizard's Hat is used in the equip/unequip cycle to help control healing skill gain while training.
//
// FLOW:
// 1) Equip Wizard's Hat (ID 5912 / 0x1718)
// 2) Unequip it
// 3) Use Bandage Self
// 4) Wait 10 seconds
// 5) Repeat until Healing reaches 100
// ============================================

while not dead

    if skill "Healing" >= 100
        overhead "HEALING 100 - STOPPING" 65
        stop
    endif

    // Equipa o hat se nao estiver na cabeca
    if not findlayer self head
        if findtype 5912 backpack as wizhat
            dclick wizhat
            wait 600
        endif
    endif

    // Desequipa o hat se estiver na cabeca
    if findlayer self head as wizhat_worn
        dclick wizhat_worn
        wait 600
    endif

    // Usa bandage self
    if not bandaging
        hotkey "Bandage Self"
        wait 650
    endif

    // Aguarda 10 segundos
    wait 10000

endwhile

// --- Auto Activate Herding Crook (Check Followers)  write by twsow with Gemini support---

// Try to find a shepherd's crook in your backpack
if findtype "shepherd's crook" backpack as myCrook
    // Found it! Get the label
    getlabel myCrook crookStatus

    // Check if 'activated' IS in the label
    if 'activated' in 'crookStatus'
        // It is already active, do nothing
    else
        // It is NOT active, check followers count
        if followers < 1
            // If less than 1 follower, do not activate
            overhead "No followers, skipping crook!" 38
        else
            // We have followers, so double click it
            dclick myCrook
            wait 500
        endif
    endif
else
    // If NO crook is found in the backpack, warn the player
    overhead "you need a crook!!" 38
    wait 1000
endif

