foreach x in ItemTypes

    while findtype x idBag as found
        hotkey 'set last target'
        target found
        @setvar myVariable lasttarget
        wait 200
        getlabel 'myVariable' myLabel
        overhead '{{myLabel}}'
        if 'unidentified' in myLabel
            skill 'itemidentification'
            waitfortarget
            target myVariable
            wait 500
        endif
        pause 500
        getlabel 'myVariable' myLabel        
        pause 200
        if 'unidentified' in myLabel
            sysmsg 'Failed ItemID' 33
            #lift myVariable 1
            #drop idBag -1 -1 0
        endif
        if 'supremely' in myLabel
            #This is the keeper routine
            sysmsg 'Keeper Item' 33
            lift myVariable 1
            drop goodBag -1 -1 0
        elseif 'invulnerability' in myLabel
            #This is the keeper routine
            sysmsg 'Keeper Item' 33
            lift myVariable 1
            drop goodBag -1 -1 0
        elseif 'vanquishing' in myLabel
            #This is the keeper routine
            sysmsg 'Keeper Item' 33
            lift myVariable 1
            drop goodBag -1 -1 0
        elseif 'enticement' in myLabel
            #This is the keeper routine
            sysmsg 'Keeper Item' 33
            lift myVariable 1
            drop goodBag -1 -1 0
        elseif 'slaying' in myLabel
            #This is the keeper routine
            sysmsg 'Keeper Item' 33
            lift myVariable 1
            drop goodBag -1 -1 0
        else
            #This stuff can be trashed
            sysmsg 'Junker' 33
            lift myVariable 1
            drop backpack -1 -1 0
            pause 500
            dclicktype 7864
            pause 500
            gumpresponse 3
            waitfortarget
            waitforgump 949095101
            targettype  x
            waitforgump 949095101
            pause 500
        endif
        @ignore myVariable
        pause 500
    endwhile
endfor

