if findtype 3651|3649|3648|3650|3708|2475|29089|29076 ground -1 -1 2 as chest
    overhead 'loot'
    foreach x in valueItems
        while findtype x chest as item
            @drop backpack
            getlabel item itemName 
            overhead '* {{itemName}} *' 6
            lift item 11111
            pause 200
            drop backpack -1 -1 0
            pause 200
            ignore item
        endwhile
    endfor

    if weight < 520
        while findtype 3821 chest as item
            @drop backpack
            if counttype 3821 chest as cGold
                overhead 'G: {{cGold}}'
            endif
            lift item 60000
            pause 200
            drop backpack -1 -1 0
            pause 200
            ignore item
        endwhile
    endif

        foreach x in ItemTypes
            if findtype x chest as item
                @drop backpack
                lift item 60000
                pause 200
                drop backpack -1 -1 0
                pause 200
                ignore item
            endif
        endfor

    overhead 'finished looting..'

endif

