            lift reagent reagentCount
            drop sourceContainer -1 -1 -1
            wait globalWaitTime
        endif

        // Pickup the amount we want from storage container
        if findtype reagentID sourceContainer as getReagent
            lift getReagent requiredReagentCount
            drop satchel -1 -1 -1
            wait globalWaitTime
        endif
    endfor
endif

