    if VetPulseActive = 0
        if timer SelfcarePulseTimer > SelfcarePulseCD
            overhead '∞SELFCARE ACTIVE∞' 53
            settimer SelfcarePulseTimer 0
        endif
    endif


    // =====================================================
    // VET HEART COUNTDOWN (NON-BLOCKING)
    // =====================================================
    if VetPulseActive = 1
        if timer VetPulseTimer > VetPulseCD

            if VetPulseStep = 4
                overhead '♥♥♥♥' 53
                @setvar! VetPulseStep 3

            else
                if VetPulseStep = 3
                    overhead '♥♥♥' 53
                    @setvar! VetPulseStep 2

                else
                    if VetPulseStep = 2
                        overhead '♥♥' 53
                        @setvar! VetPulseStep 1

                    else
                        if VetPulseStep = 1
                            overhead '♥' 53
                            @setvar! VetPulseStep 0
                        endif
                    endif
                endif
            endif

            settimer VetPulseTimer 0

            if VetPulseStep = 0
                @setvar! VetPulseActive 0
                overhead '∞SELFCARE ACTIVE∞' 53
                settimer SelfcarePulseTimer 0
            endif

        endif
    endif


    // =====================================================
    // 1) VET SUPPLY — HIGHEST PRIORITY
    // =====================================================
    if petHealLOOP = 1
        if hp < MaxHealth
            if not bandaging
                if timer VetSuppTimer > VetSuppTimerCD
                    if findtype 'veterinary supplies' backpack as vetsupp

                        dclick vetsupp
                        settimer VetSuppTimer 0
                        wait 400

                        if VetPulseActive = 0
                            @setvar! VetPulseActive 1
                            overhead '♥♥♥♥♥' 53
                            @setvar! VetPulseStep 4
                            settimer VetPulseTimer 0
                        endif

                    endif
                endif
            endif
        endif
    endif


    // =====================================================
    // 2) HEAL POTION
    // =====================================================
    if heal_potion = 1
        if hp < 60
            if timer HealPotionTimer > HealPotionCD
                hotkey 'Drink Heal'
                overhead 'Heal Potion' 53
                settimer HealPotionTimer 0
                wait 350
            endif
        endif
    endif


    // =====================================================
    // 3) CURE / PANACEA
    // =====================================================
    if cure_potion = 1
        if timer CurePotionTimer > CurePotionCD

            if poisoned
                hotkey 'Drink Cure'
                overhead 'Cure (Poison)' 53
                settimer CurePotionTimer 0
                wait 350

            else
                if findbuff 'Diseased'
                    hotkey 'Drink Cure'
                    overhead 'Cure (Disease)' 53
                    settimer CurePotionTimer 0
                    wait 350

                else
                    if findbuff 'Bleeding'
                        hotkey 'Drink Cure'
                        overhead 'Cure (Bleed)' 53
                        settimer CurePotionTimer 0
                        wait 350
                    endif
                endif
            endif

        endif
    endif


    // =====================================================
    // 4) REFRESH POTION
    // =====================================================
    if refresh_potion = 1
        if stam < 50
            if timer RefreshPotionTimer > RefreshPotionCD
                hotkey 'Drink Refresh'
                overhead 'Refresh Potion' 53
                settimer RefreshPotionTimer 0
                wait 300
            endif
        endif
    endif


    // =====================================================
    // 5) BUFF POTIONS — WARMODE ONLY
    // =====================================================
    if buffs_potion = 1
        if warmode 1
            if timer BuffPotionTimer > BuffPotionCD

                if not findbuff 'Strength'
                    hotkey 'Drink Strength'
                    overhead 'STR Potion' 53
                    settimer BuffPotionTimer 0
                    wait 900
                endif

                if not findbuff 'Agility'
                    hotkey 'Drink Agility'
                    overhead 'AGI Potion' 53
                    settimer BuffPotionTimer 0
                    wait 900
                endif

                if not findbuff 'Magic Resist'
                    hotkey 'Drink Magic Resist'
                    overhead 'MR Potion' 53
                    settimer BuffPotionTimer 0
                    wait 900
                endif

            endif
        endif
    endif


    // =====================================================
    // 6) POUCH — PARALYSIS
    // =====================================================
    if pouch = 1
        if paralyzed
            if timer PouchTimer > PouchCD
                say [pouch
                settimer PouchTimer 0
                wait 200
            endif
        endif
    endif


    // =====================================================
    // 7) OVERWEIGHT GOLD DROP
    // =====================================================
    if weight > maxweight

        if timer overweightMessageTimer > overweightMessageCD
            overhead 'Overweight !!' 34
            settimer overweightMessageTimer 0
        endif

        if amountOfGoldToDrop > 0
            if findtype 3821 backpack as goldpile
                lift goldpile amountOfGoldToDrop
                droprelloc 0 0
                wait 300
                overhead '* Gold Dropped *' 55
            endif
        endif

    endif


    // =====================================================
    // 8) FOOD / AUTO-EAT
    // =====================================================
    if food = 1
        if not findbuff 'Food Satisfaction'
            if findtype 'tray' backpack as foodtray
                dclick foodtray
                wait 300
            endif
        endif
    endif


    wait 60

endwhile

